-- RRC091: MariaDB10.11, dedicated fresh admin session; manual coordinated application only.
-- Source recipe facts/provenance: batch.public.json. No engine/updater/version/rule changes.
-- Anonymous compound block: no permanent helper procedure or migration table.
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE own_transaction BOOLEAN DEFAULT FALSE;
 DECLARE already_present INT DEFAULT 0;
 DECLARE recipes_before BIGINT DEFAULT 0;
 DECLARE entries_before BIGINT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  IF own_transaction THEN ROLLBACK; END IF;
  RESIGNAL;
 END;
 IF @@in_transaction <> 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 requires fresh transaction-free session'; END IF;
 IF FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)=0 AND FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 strict SQL mode required'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('tradeskill_recipe','tradeskill_recipe_entries','items') AND ENGINE='InnoDB')<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 InnoDB foundation mismatch'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe')<>16 OR (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe_entries')<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 recipe schema column-count mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc091_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc091_parents LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc091_parent_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc091_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc091_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
 START TRANSACTION;
 SET own_transaction=TRUE;
 IF EXISTS(SELECT 1 FROM rrc091_parents e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 prototype drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc091_parent_entries e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc091_parents p ON p.id=r.recipe_id)<>825 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 prototype entries drift'; END IF;
 SELECT COUNT(*) INTO recipes_before FROM tradeskill_recipe;
 SELECT COUNT(*) INTO entries_before FROM tradeskill_recipe_entries;
 SELECT COUNT(*) INTO already_present FROM tradeskill_recipe r JOIN rrc091_recipes e ON r.id=e.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM rrc091_items e LEFT JOIN items i ON i.id=e.id WHERE i.id IS NULL OR BINARY i.Name<>BINARY e.name) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 item identity/dependency mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=93492 AND itemclass=1 AND bagtype=11 AND bagslots=10 AND bagsize=3 AND classes=15360)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 native kit mismatch'; END IF; IF (SELECT COUNT(*) FROM items WHERE (id=78730 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=16384) OR (id=97824 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93542 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93587 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93579 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93553 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93521 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=78820 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=1024) OR (id=93545 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93578 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93516 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93540 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=78841 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=1024) OR (id=93577 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93565 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=97821 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=78860 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=1024) OR (id=93555 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=97822 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93589 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93590 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93539 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=78976 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=8192) OR (id=93556 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93514 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=97823 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93543 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=79058 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93515 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=79070 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93537 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=79101 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93557 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93572 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=79157 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=2048) OR (id=93517 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=79188 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=2048) OR (id=93561 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360))<>38 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 input/output semantics mismatch'; END IF; IF (SELECT COUNT(*) FROM items WHERE (id=78730 AND itemtype=20 AND scrolleffect=10393 AND scrolllevel=0 AND reqlevel=0) OR (id=78820 AND itemtype=20 AND scrolleffect=10483 AND scrolllevel=0 AND reqlevel=0) OR (id=78841 AND itemtype=20 AND scrolleffect=10504 AND scrolllevel=0 AND reqlevel=0) OR (id=78860 AND itemtype=20 AND scrolleffect=10523 AND scrolllevel=0 AND reqlevel=0) OR (id=78976 AND itemtype=20 AND scrolleffect=10639 AND scrolllevel=0 AND reqlevel=0) OR (id=79058 AND itemtype=20 AND scrolleffect=10721 AND scrolllevel=0 AND reqlevel=0) OR (id=79070 AND itemtype=20 AND scrolleffect=10733 AND scrolllevel=0 AND reqlevel=0) OR (id=79101 AND itemtype=20 AND scrolleffect=10764 AND scrolllevel=0 AND reqlevel=0) OR (id=79157 AND itemtype=20 AND scrolleffect=10820 AND scrolllevel=0 AND reqlevel=0) OR (id=79188 AND itemtype=20 AND scrolleffect=10851 AND scrolllevel=0 AND reqlevel=0))<>10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 Tome spell binding mismatch'; END IF;
 IF already_present NOT IN (0,10) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 partial batch or ID collision'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe r JOIN rrc091_recipes e ON r.tradeskill=e.tradeskill AND r.name=e.name WHERE r.id<>e.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 existing recipe-name collision'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc091_entries e ON r.item_id=e.item_id JOIN rrc091_recipes q ON e.recipe_id=q.id WHERE e.successcount>e.componentcount AND e.iscontainer=0 AND r.successcount>r.componentcount AND r.iscontainer=0 AND r.recipe_id<>e.recipe_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 existing output recipe collision'; END IF;
 IF already_present=0 THEN
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc091_recipes e ON r.recipe_id=e.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 orphan target entries collision'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM rrc091_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`name` <=> e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND r.`notes` <=> e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND r.`content_flags` <=> e.`content_flags` AND r.`content_flags_disabled` <=> e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 recipe postimage mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc091_entries e LEFT JOIN tradeskill_recipe_entries r ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE r.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 expected entry absent'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc091_recipes q ON q.id=r.recipe_id LEFT JOIN rrc091_entries e ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE e.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 foreign/different target entries'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc091_recipes q ON q.id=r.recipe_id)<>77 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 target entry multiplicity mismatch'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe)<>recipes_before+IF(already_present=0,10,0) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries)<>entries_before+IF(already_present=0,77,0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 unexpected table row-count delta'; END IF;
 IF EXISTS(SELECT 1 FROM rrc091_parents e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 prototype drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc091_parent_entries e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc091_parents p ON p.id=r.recipe_id)<>825 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC091 prototype entries drift'; END IF;
 DROP TEMPORARY TABLE rrc091_parents;
 DROP TEMPORARY TABLE rrc091_parent_entries;
 DROP TEMPORARY TABLE rrc091_entries;
 DROP TEMPORARY TABLE rrc091_recipes;
 DROP TEMPORARY TABLE rrc091_items;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC091' AS batch,already_present AS previous_recipe_count,recipes_before AS recipes_before,(SELECT COUNT(*) FROM tradeskill_recipe) AS recipes_after,entries_before AS entries_before,(SELECT COUNT(*) FROM tradeskill_recipe_entries) AS entries_after,@@in_transaction AS in_transaction;
END//
DELIMITER ;
